  "extras": [
    {
      "after_item": "S10_END",
      "title_raw": "가. 화학적 안정성 및 유해 반응의 가능성",
      "reason": "필드없음",
      "statements": [
        {
          "value": "화재에 노출된 실린더는 가연성 가스를 방출할 수 있음.",
          "line": "p6:L27"
        },
        {
          "value": "가열시 용기가 폭발할 수 있음.",
          "line": "p6:L28"
        },
        {
          "value": "가열시 증기는 공기와 혼합하여 폭발성 혼합물을 형성할 수 있음; 실내, 실외, 하수구에 폭발 위험.",
          "line": "p6:L29"
        },
        {
          "value": "격렬하게 중합반응하여 화재와 폭발을 일으킬 수 있음.",
          "line": "p6:L30"
        },
        {
          "value": "공기와 폭발성 혼합물을 형성함.",
          "line": "p6:L31"
        },
        {
          "value": "극인화성.",
          "line": "p6:L32"
        },
        {
          "value": "열, 스파크, 화염에 의해 쉽게 점화함.",
          "line": "p7:L1"
        },
        {
          "value": "일부는 탈 수 있으나 쉽게 점화하지 않음.",
          "line": "p7:L2"
        },
        {
          "value": "증기는 점화원까지 이동하여 역화(flash back)할 수 있음.",
          "line": "p7:L3"
        },
        {
          "value": "화재시 자극성, 부식성, 독성 가스를 발생할 수 있음.",
          "line": "p7:L4"
        }
      ],
      "line": "p6:L26"
    },
    {
      "after_item": "S10_STABILITY",
      "title_raw": "나. 피해야 할 조건",
      "reason": "필드없음",
      "statements": [
        {
          "value": "열, 스파크, 화염 등 점화원.",
          "line": "p7:L6"
        },
        {
          "value": "열, 오염.",
          "line": "p7:L7"
        }
      ],
      "line": "p7:L5"
    },
    {
      "after_item": "S10_CONDITIONS",
      "title_raw": "다. 피해야 할 물질",
